; flagtest.asm -- chapter 7: which flags each instruction sets
; generated by gen07.py
        INCLUDE "msx.inc"
        OUTPUT "flagtest.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
; ld a, b, with every flag clear
        ld b, $01
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        ld a, b
        push af
        pop iy
        ld (RESULTS + 0), iy         ; F, then A
; ld a, b, with every flag set
        ld b, $01
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        ld a, b
        push af
        pop iy
        ld (RESULTS + 2), iy         ; F, then A
; add a, b, with every flag clear
        ld b, $01
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        add a, b
        push af
        pop iy
        ld (RESULTS + 4), iy         ; F, then A
; add a, b, with every flag set
        ld b, $01
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        add a, b
        push af
        pop iy
        ld (RESULTS + 6), iy         ; F, then A
; sub b, with every flag clear
        ld b, $01
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        sub b
        push af
        pop iy
        ld (RESULTS + 8), iy         ; F, then A
; sub b, with every flag set
        ld b, $01
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        sub b
        push af
        pop iy
        ld (RESULTS + 10), iy         ; F, then A
; cp b, with every flag clear
        ld b, $01
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        cp b
        push af
        pop iy
        ld (RESULTS + 12), iy         ; F, then A
; cp b, with every flag set
        ld b, $01
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        cp b
        push af
        pop iy
        ld (RESULTS + 14), iy         ; F, then A
; inc a, with every flag clear
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        inc a
        push af
        pop iy
        ld (RESULTS + 16), iy         ; F, then A
; inc a, with every flag set
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        inc a
        push af
        pop iy
        ld (RESULTS + 18), iy         ; F, then A
; dec a, with every flag clear
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        dec a
        push af
        pop iy
        ld (RESULTS + 20), iy         ; F, then A
; dec a, with every flag set
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        dec a
        push af
        pop iy
        ld (RESULTS + 22), iy         ; F, then A
; and b, with every flag clear
        ld b, $0F
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        and b
        push af
        pop iy
        ld (RESULTS + 24), iy         ; F, then A
; and b, with every flag set
        ld b, $0F
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        and b
        push af
        pop iy
        ld (RESULTS + 26), iy         ; F, then A
; or b, with every flag clear
        ld b, $0F
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        or b
        push af
        pop iy
        ld (RESULTS + 28), iy         ; F, then A
; or b, with every flag set
        ld b, $0F
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        or b
        push af
        pop iy
        ld (RESULTS + 30), iy         ; F, then A
; xor b, with every flag clear
        ld b, $0F
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        xor b
        push af
        pop iy
        ld (RESULTS + 32), iy         ; F, then A
; xor b, with every flag set
        ld b, $0F
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        xor b
        push af
        pop iy
        ld (RESULTS + 34), iy         ; F, then A
; rlca, with every flag clear
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
