        push af
        pop iy
        ld (RESULTS + 40), iy         ; F, then A
; cpl, with every flag set
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        cpl
        push af
        pop iy
        ld (RESULTS + 42), iy         ; F, then A
; neg, with every flag clear
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        neg
        push af
        pop iy
        ld (RESULTS + 44), iy         ; F, then A
; neg, with every flag set
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        neg
        push af
        pop iy
        ld (RESULTS + 46), iy         ; F, then A
; scf, with every flag clear
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        scf
        push af
        pop iy
        ld (RESULTS + 48), iy         ; F, then A
; scf, with every flag set
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        scf
        push af
        pop iy
        ld (RESULTS + 50), iy         ; F, then A
; inc hl, with every flag clear
        ld hl, $FFFF
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        inc hl
        push af
        pop iy
        ld (RESULTS + 52), iy         ; F, then A
; inc hl, with every flag set
        ld hl, $FFFF
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
