        push af
        pop iy
        ld (RESULTS + 54), iy         ; F, then A
; dec bc, with every flag clear
        ld bc, $0001
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        dec bc
        push af
        pop iy
        ld (RESULTS + 56), iy         ; F, then A
; dec bc, with every flag set
