        push af
        pop iy
        ld (RESULTS + 58), iy         ; F, then A
; add hl, de, with every flag clear
        ld hl, $FFFF
        ld de, $0001
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        add hl, de
        push af
        pop iy
        ld (RESULTS + 60), iy         ; F, then A
; add hl, de, with every flag set
        ld hl, $FFFF
        ld de, $0001
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        add hl, de
        push af
        pop iy
        ld (RESULTS + 62), iy         ; F, then A
; out (PSG_ADDR), a, with every flag clear
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        out (PSG_ADDR), a
        push af
        pop iy
        ld (RESULTS + 64), iy         ; F, then A
; out (PSG_ADDR), a, with every flag set
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        out (PSG_ADDR), a
        push af
        pop iy
        ld (RESULTS + 66), iy         ; F, then A
; jr $+2, with every flag clear
        ld iy, $FF00
        push iy
        pop af                  ; A = $FF, F = $00
        jr $+2
        push af
        pop iy
        ld (RESULTS + 68), iy         ; F, then A
; jr $+2, with every flag set
        ld iy, $FFFF
        push iy
        pop af                  ; A = $FF, F = $FF
        jr $+2
        push af
        pop iy
        ld (RESULTS + 70), iy         ; F, then A
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
